class Solution {
    public int numUniqueEmails(String[] emails){
        Set<String> unique=new HashSet<>();
        for(String email:emails){
            int at=email.indexOf('@');
            String local=email.substring(0,at),domain=email.substring(at);
            int plus=local.indexOf('+');
            if(plus>=0)local=local.substring(0,plus);
            unique.add(local.replace(".","")+domain);
        }
        return unique.size();
    }
}

code.kotlin:
class Solution {
    fun numUniqueEmails(emails:Array<String>):Int{
        val unique=mutableSetOf<String>();
        for(email in emails){
            val at=email.indexOf('@');
            var local=email.substring(0,at);
            val plus=local.indexOf('+');
            if(plus>=0)local=local.substring(0,plus);
            unique.add(local.replace(".","")+email.substring(at))
        };
        return unique.size
    }
}

code.cpp:
class Solution {
    public: int numUniqueEmails(vector<string>& emails){
        unordered_set<string> unique;
        for(string email:emails){
            int at=email.find('@'),plus=email.find('+');
            string local=email.substr(0,min(at,plus<0?at:plus)),clean;
            for(char ch:local)if(ch!='.')clean+=ch;
            unique.insert(clean+email.substr(at));
        }
        return unique.size();
    }
};
